.message-bubble h3 { font-size: 0.98rem; color: var(--text-secondary); margin: 10px 0 4px; font-weight: 600; }
.message-bubble p  { margin: 6px 0; }
.message-bubble ul, .message-bubble ol { padding-left: 20px; margin: 6px 0; }
.message-bubble li { margin: 3px 0; }
.message-bubble strong { color: var(--text-primary); }
.message-bubble a  { color: var(--accent-light); text-decoration: none; }
.message-bubble a:hover { text-decoration: underline; }
.message-bubble hr { border: none; border-top: 1px solid var(--border); margin: 14px 0; }
.message-bubble code {
  background: var(--bg-input);
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 0.87em;
  color: var(--accent-light);
}
.message-bubble pre {
  background: var(--bg-input);
  border-radius: var(--radius-sm);
  padding: 12px;
  overflow-x: auto;
  margin: 8px 0;
}
.message-bubble pre code { background: none; padding: 0; }
.disclaimer-note {
  font-size: 0.82rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  padding-top: 8px;
  margin-top: 10px;
}

/* Inline chart images */
.chart-img {
  max-width: 100%;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  margin-top: 10px;
}

/* Typing indicator */
.typing-indicator {
  display: flex;
  gap: 5px;
  padding: 14px 18px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  width: fit-content;
  margin-top: 8px;
}
.typing-indicator span {
  width: 7px; height: 7px;
  background: var(--text-muted);
  border-radius: 50%;
  animation: bounce 1.2s infinite;
}
.typing-indicator span:nth-child(2) { animation-delay: 0.2s; }
.typing-indicator span:nth-child(3) { animation-delay: 0.4s; }
@keyframes bounce {
  0%, 60%, 100% { transform: translateY(0); }
  30% { transform: translateY(-6px); background: var(--accent); }
}

/* ── Reasoning Steps ─────────────────────────────────────────────── */
.steps-header { padding: 16px 0 8px; }
.steps-header h2 { font-size: 1rem; font-weight: 700; color: var(--text-primary); }
.steps-header p { font-size: 0.82rem; color: var(--text-secondary); margin-top: 4px; }

.steps-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}
.steps-empty { color: var(--text-muted); font-size: 0.88rem; padding: 24px; text-align: center; }

.step-item {
  display: flex;
  gap: 12px;
  padding: 10px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  animation: fadeIn 0.25s ease;
  align-items: flex-start;
}
.step-item.step-tool_call    { border-left: 3px solid var(--accent); }
.step-item.step-tool_result  { border-left: 3px solid var(--text-muted); }
.step-item.step-agent_start  { border-left: 3px solid var(--warning); }
.step-item.step-agent_done   { border-left: 3px solid var(--success); }
.step-item.step-critique_done { border-left: 3px solid #a78bfa; }
.step-item.step-error        { border-left: 3px solid var(--danger); }

